"""Snap span times to a payroll step and label the results."""

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step):
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def _snap(minute, step):
    """Nearest multiple of step. Halfway rounds up."""
    return (minute + step // 2) // step * step


def _round(span, step):
    return Span(
        _snap(span.start, step),
        _snap(span.end, step)
    )


def _label(span):
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"


# ---
def rounded_labels(spans, step):
    """One label per span, such as 09:00-17:15 (8h 15m).

    A step that is not positive or does not divide an hour
    raises ValueError. So does a span that shrinks to nothing.
    """
    _check_step(step)
    rounded = [_round(s, step) for s in spans]
    return [_label(s) for s in rounded]

