# owner: platform
import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span


class LabelTests(unittest.TestCase):
    # ---
    def test_label_format(self):
        self.assertEqual(
            rounded_labels([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    # ---
    def test_rounds_to_nearest(self):
        self.assertEqual(
            rounded_labels([Span(543, 1028)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    # ---
    def test_halfway_rounds_up(self):
        self.assertEqual(
            rounded_labels([Span(555, 660)], 30),
            ["09:30-11:00 (1h 30m)"]
        )

    # ---
    def test_empty_and_order(self):
        self.assertEqual(rounded_labels([], 5), [])
        labels = rounded_labels(
            [Span(600, 660), Span(60, 120)], 30
        )
        self.assertEqual(labels[1][:5], "01:00")

    # ---
    def test_end_of_day(self):
        self.assertEqual(
            rounded_labels([Span(1400, 1440)], 30),
            ["23:30-24:00 (0h 30m)"]
        )


class StepTests(unittest.TestCase):
    # ---
    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 120):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

    # ---
    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 15, 30, 60):
            rounded_labels([Span(0, 120)], step)

    # ---
    def test_span_shrunk_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(61, 64)], 15)


if __name__ == "__main__":
    unittest.main()
